# Global inverted slang index for instant cross-lingual lookup: term -> [(lang, definition), ...]
_GLOBAL_SLANG_INDEX = {}
for _lang, _terms in SLANG_BY_LANGUAGE.items():
    for _t, _def in _terms.items():
        _tl = _t.lower().strip()
        if _tl not in _GLOBAL_SLANG_INDEX:
            _GLOBAL_SLANG_INDEX[_tl] = []
        _GLOBAL_SLANG_INDEX[_tl].append((_lang, _def))


def is_known_word(word: str, lang: str = None) -> bool:
    """
    Checks if a word exists in the dictionary of the specified language,
    or across any supported language if lang is None.
    """
    if not word or not isinstance(word, str):
        return False
    w = word.lower().strip()
    if lang and lang in LANGUAGE_DICTIONARIES:
        return w in LANGUAGE_DICTIONARIES[lang]
    # Check across all language dictionaries
    return any(w in dict_set for dict_set in LANGUAGE_DICTIONARIES.values())


def get_slang_meaning(word: str, lang: str = None) -> dict | None:
    """
    Searches for a slang term in the specified language or across all 101 languages.
    Returns dict: {'term': str, 'definition': str, 'language': str} or None.
    """
    if not word or not isinstance(word, str):
        return None
    w = word.lower().strip()
    
    # 1. Targeted search by language
    if lang and lang in SLANG_BY_LANGUAGE:
        if w in SLANG_BY_LANGUAGE[lang]:
            return {
                'term': w,
                'definition': SLANG_BY_LANGUAGE[lang][w],
                'language': lang
            }
            
    # 2. Universal global inverted index lookup
    if w in _GLOBAL_SLANG_INDEX:
        hit_lang, hit_def = _GLOBAL_SLANG_INDEX[w][0]
        return {
            'term': w,
            'definition': hit_def,
            'language': hit_lang
        }
        
    return None


def detect_word_language(word: str) -> str:
    """
    Detects the primary language of a word based on vocabulary presence and script heuristics.
    Returns the two-letter language code or 'unknown'.
    """
    if not word or not isinstance(word, str):
        return 'unknown'
    w = word.lower().strip()
    
    # Fast check in language dictionaries
    candidates = []
    for code, dict_set in LANGUAGE_DICTIONARIES.items():
        if w in dict_set:
            candidates.append(code)
            
    if len(candidates) == 1:
        return candidates[0]
    elif len(candidates) > 1:
        # Prioritize major world languages if tied
        for prio in ['ru', 'kk', 'en', 'zh', 'es', 'de', 'fr', 'ar', 'ja']:
            if prio in candidates:
                return prio
        return candidates[0]
        
    # Script heuristics
    if re.search(r'[Ѐ-ӿ]', w):  # Cyrillic
        if any(c in w for c in 'әіңғүұқөһ'):
            return 'kk'
        elif any(c in w for c in 'іїєґ'):
            return 'uk'
        return 'ru'
    elif re.search(r'[一-鿿]', w):  # Chinese Hanzi
        return 'zh'
    elif re.search(r'[぀-ヿ]', w):  # Japanese Kana
        return 'ja'
    elif re.search(r'[가-힯]', w):  # Korean Hangul
        return 'ko'
    elif re.search(r'[؀-ۿ]', w):  # Arabic script
        return 'ar'
    elif re.search(r'[ऀ-ॿ]', w):  # Devanagari (Hindi/Marathi)
        return 'hi'
    elif re.search(r'[֐-׿]', w):  # Hebrew
        return 'he'
    elif re.search(r'[฀-๿]', w):  # Thai
        return 'th'
    elif re.search(r'[Ⴀ-ჿ]', w):  # Georgian
        return 'ka'
    elif re.search(r'[԰-֏]', w):  # Armenian
        return 'hy'
        
    return 'en' if re.match(r'^[a-z]+$', w) else 'unknown'


def get_dictionary_stats() -> dict:
    """
    Returns telemetry metrics on all 101 language dictionaries and slang matrices.
    """
    total_vocab = sum(len(s) for s in LANGUAGE_DICTIONARIES.values())
    total_slang = sum(len(d) for d in SLANG_BY_LANGUAGE.values())
    return {
        'total_languages': len(LANGUAGE_DICTIONARIES),
        'total_vocabulary_words': total_vocab,
        'total_slang_terms': total_slang,
        'languages': list(LANGUAGE_DICTIONARIES.keys())
    }


def lookup_word(word: str, lang: str = None) -> dict:
    """
    Comprehensive word inspection across both standard vocabulary and slang matrix.
    """
    w = word.lower().strip()
    detected_lang = detect_word_language(w)
    is_known = is_known_word(w, lang)
    slang_info = get_slang_meaning(w, lang)
    
    return {
        'word': word,
        'detected_language': detected_lang,
        'is_standard_word': is_known,
        'is_slang': slang_info is not None,
        'slang_details': slang_info
    }
